+#include <unistd.h>
+#include <fcntl.h>
+static struct shift_trace_data {
+    int pos = 0, rows = 0;
+    std::string path, ref, force;
+    bool verify = false;
+    void transfer(const std::string & file, void * data, size_t size, size_t offset, bool writing) {
+        int fd = open(file.c_str(), writing ? (O_CREAT | O_WRONLY) : O_RDONLY, 0600);
+        GGML_ASSERT(fd >= 0);
+        auto n = writing ? pwrite(fd,data,size,offset) : pread(fd,data,size,offset);
+        GGML_ASSERT(n == ssize_t(size)); close(fd);
+    }
+} shift_trace;
+static bool shift_observe(ggml_tensor * t, bool ask, void *) {
+    const std::string name(t->name);
+    bool mix = name.find("attn_residual-")==0, end = name.find("l_out-")==0;
+    if (!mix && !end) return false;
+    if (ask) return true;
+    auto & d = shift_trace;
+    GGML_ASSERT(t->type==GGML_TYPE_F32 && t->ne[0]==2048 && ggml_is_contiguous(t));
+    size_t n=ggml_nelements(t)/2048; GGML_ASSERT(n==size_t(d.rows)||n<=1);
+    if (!n) return true;
+    size_t pos = d.verify ? 0 : d.pos + (n==1 ? d.rows-1 : 0);
+    if (d.verify) n=1;
+    size_t len=n*8192, offset=pos*8192;
+    std::vector<float> val(len/4);
+    ggml_backend_tensor_get(t,val.data(),0,len);
+    auto suffix= std::string(d.verify ? "/v-" : "/p-") + name;
+    d.transfer(d.path+suffix,val.data(),len,offset,true);
+    if (!d.verify && !d.force.empty()) {
+        int il = std::stoi(name.substr(name.rfind('-')+1));
+        bool chosen = d.force=="both" || (end && d.force=="moe") ||
+                     (mix && (d.force=="mix" || d.force==(il%4==3?"attn":"gdn")));
+        if (chosen) {
+            d.transfer(d.ref+suffix,val.data(),len,offset,false);
+            ggml_backend_tensor_set(t,val.data(),0,len);
+        }
+    }
+    return true;
+}
+static void shift_cache(ggml_cgraph * gf, const std::string & path,const std::string & ref,const std::string & mode) {
+    const char * store = std::getenv("SHIFT_STATE_SAVE");
+    if (!store && mode.empty()) return;
+    for (int il=0;il<40;++il) {
+        const bool attn=il%4==3;
+        if (!store && !(mode=="all" || mode==(attn ? "attn" : "gdn") || mode==std::to_string(il))) continue;
+        for(char code:std::string(attn?"kv":"rs")) {
+            const auto name=std::string("cache_")+code+"_l"+std::to_string(il);
+            ggml_tensor * t=ggml_graph_get_tensor(gf,name.c_str());
+            GGML_ASSERT(t && t->buffer && ggml_is_contiguous(t));
+            // Full KV storage includes padding. Recurrent storage includes rollback rows.
+            auto bytes=ggml_nbytes(t);
+            std::vector<char> block(std::min(bytes,size_t(1)<<20));
+            for (size_t off=0;off<bytes;off+=block.size()) {
+                size_t len=std::min(bytes-off,block.size());
+                if (store) {
+                    ggml_backend_tensor_get(t,block.data(),off,len);
+                    shift_trace.transfer(path+"/"+name,block.data(),len,off,true);
+                } else {
+                    shift_trace.transfer(ref+"/"+name,block.data(),len,off,false);
+                    ggml_backend_tensor_set(t,block.data(),off,len);
+                }
+            }
+        }
+    }
+}
+struct shift_segment_plan {
+    int first, last, final;
+    std::string path;
+};
+static bool shift_edge(ggml_tensor * t,bool ask,void * user) {
+    auto & g = *(shift_segment_plan*)user; auto & d=shift_trace;
+    const std::string key(t->name);
+    bool mix=key.find("attn_residual-")==0, end=key.find("l_out-")==0;
+    if(!mix && !end) return false;
+    int b=2*std::stoi(key.substr(key.rfind('-')+1)) + int(end);
+    if (b!=g.first-1 && b!=g.last) return false;
+    if (ask) return true;
+    GGML_ASSERT(t->type==GGML_TYPE_F32 && t->ne[0]==2048 && ggml_is_contiguous(t));
+    size_t n=ggml_nelements(t)/2048;
+    if (!n) return true;
+    GGML_ASSERT(n==size_t(d.rows) || n==1);
+    size_t off=(d.pos+(n==1?d.rows-1:0))*8192, len=n*8192;
+    std::vector<float> val(len/4);
+    std::string file=g.path+"/edge"+std::to_string(b);
+    if (b==g.last) {
+        ggml_backend_tensor_get(t,val.data(),0,len);
+        d.transfer(file,val.data(),len,off,true);
+    } else {
+        d.transfer(file,val.data(),len,off,false);
+        ggml_backend_tensor_set(t,val.data(),0,len);
+    }
+    return true;
+}
+static void shift_segment_state(ggml_cgraph * gf,const shift_segment_plan & g,bool restore) {
+    for(int il=0;il<40;il++) {
+        if(restore ? 2*il>=g.first : (2*il<g.first || 2*il>g.last))continue;
+        for(char code:std::string(il%4==3 ? "kv" : "rs")) {
+            const auto name=std::string("cache_")+code+"_l"+std::to_string(il);
+            auto * t=ggml_graph_get_tensor(gf,name.c_str()); GGML_ASSERT(t && t->buffer && ggml_is_contiguous(t));
+            auto bytes=ggml_nbytes(t);
+            std::vector<char> block(std::min(bytes,size_t(4)<<20));
+            for(size_t off=0;off<bytes;off+=block.size()){
+                size_t len=std::min(bytes-off,block.size());
+                if(restore){
+                    shift_trace.transfer(g.path+"/"+name,block.data(),len,off,false);
+                    ggml_backend_tensor_set(t,block.data(),off,len);
+                }else{
+                    ggml_backend_tensor_get(t,block.data(),off,len);
+                    shift_trace.transfer(g.path+"/"+name,block.data(),len,off,true);
+                }
+            }
+        }
+    }
+}
